// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    Token token;

    // The factory address passed to C is this test contract; C's changeFeeQuote
    // calls Factory(factory).protocolFeeRate(), so provide it.
    function protocolFeeRate() external view returns (uint16) {
        return 0;
    }

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
        token = new Token();
    }

    function testFuzz_property(uint56 changeFee, uint16 feeRate) public {
        vm.assume(feeRate <= 5_000);

        c.initialize(address(token), address(token), 1e18, 1e18, changeFee, feeRate, bytes32(0), false, false);

        // With an ERC20 base token of 6 decimals, changeFeeQuote must use
        // exponent = decimals - 4 = 2, i.e. feePerNft = changeFee * 100.
        (uint256 feeAmount,) = c.changeFeeQuote(1e18);
        assertTrue(feeAmount == uint256(changeFee) * 100);
    }
}

contract Token {
    function decimals() external pure returns (uint8) {
        return 6;
    }
}
